INSERT INTO "exercises" ("slug", "name", "category", "equipment", "cues", "safety_notes", "reviewed") VALUES
('trap-bar-deadlift', 'Trap bar deadlift', 'STRENGTH', '["trap bar","weight plates"]', 'Hinge at hips, grip neutral handles, chest proud, drive the floor away through mid-foot.', 'Maintain neutral spine throughout pull. Avoid rounding upper or lower back.', false),
('front-squat', 'Front squat', 'STRENGTH', '["barbell","squat rack"]', 'Keep elbows high, torso upright, sit between hips below parallel, drive up forcefully.', 'Requires wrist and thoracic mobility. Use safety bars in rack.', false),
('bulgarian-split-squat', 'Bulgarian split squat', 'STRENGTH', '["dumbbells","bench"]', 'Place rear foot laces-down on bench. Lower until front thigh is parallel to floor. Drive through front heel.', 'Keep torso slightly inclined forward to load hips and protect rear knee.', false),
('db-bench-press', 'Dumbbell bench press', 'STRENGTH', '["dumbbells","flat bench"]', 'Retract shoulder blades into bench. Lower dumbbells with 45-degree elbow tuck, press together overhead.', 'Avoid flaring elbows 90 degrees out to protect anterior shoulder.', false),
('pull-up', 'Pull-up', 'STRENGTH', '["pull-up bar"]', 'Overhand grip just outside shoulders. Initiate pull from lats, bring collarbone to bar, control descent.', 'Avoid excessive swinging or kipping if targeting pure vertical pulling strength.', false),
('single-leg-rdl', 'Single-leg Romanian deadlift', 'STRENGTH', '["dumbbell or kettlebell"]', 'Soft knee on standing leg. Hinge hips back while reaching back leg straight. Keep pelvis level.', 'Prioritize balance and hip control over heavy weights.', false),
('push-press', 'Push press', 'STRENGTH', '["barbell or dumbbells"]', 'Dip knees 3 to 4 inches quickly. Drive through heels and transfer leg drive into overhead press.', 'Lock core and glutes at apex to prevent hyperextending lower lumbar spine.', false),
('depth-jump', 'Depth jump', 'POWER', '["box 30-45cm"]', 'Step off box without jumping. Absorb landing briefly and instantly explode upward for max height.', 'High neuromuscular demand. Only perform on dry, non-slip surfaces.', false),
('seated-box-jump', 'Seated box jump', 'POWER', '["two boxes or bench and box"]', 'Sit on bench with hips relaxed. Rock forward and explode onto target box without a countermovement.', 'Removes stretch reflex to build pure starting power and rate of force development.', false),
('countermovement-jump', 'Countermovement jump (CMJ)', 'POWER', '["none"]', 'Stand tall, swing arms back while rapidly dipping into quarter squat, violently reverse and jump as high as possible.', 'Primary basketball vertical jump assessment. Land softly with knees bent.', false),
('single-leg-box-jump', 'Single-leg box jump', 'POWER', '["low box 15-30cm"]', 'Balance on one leg, dip and explode onto low box, land softly absorbing impact.', 'Start low to master single-leg deceleration before increasing box height.', false),
('med-ball-chest-pass', 'Medicine ball chest pass', 'POWER', '["medicine ball 3-5kg","wall or partner"]', 'Athletic stance, hold ball at chest. Step forward and violently push ball outward against wall.', 'Focus on maximal release velocity and explosive triple extension.', false),
('skater-bounds', 'Skater bounds', 'PLYOMETRIC', '["open space"]', 'Push off outside edge of one foot, bound laterally 4 to 6 feet, land and absorb on opposite foot with soft knee.', 'Develops lateral deceleration and change of direction required for Euro-steps.', false),
('tuck-jumps', 'Continuous tuck jumps', 'PLYOMETRIC', '["none"]', 'Jump repeatedly off balls of feet, bringing knees toward chest in mid-air. Minimize ground contact time.', 'Perform on shock-absorbing floor. Stop if jumping height noticeably decreases.', false),
('single-leg-pogo-hops', 'Single-leg pogo hops', 'PLYOMETRIC', '["none"]', 'Hop on one foot with stiff ankle. Quick rebound off forefoot like a pogo stick.', 'High Achilles tendon loading. Keep sets under 10 seconds.', false),
('hurdle-hops', 'Mini-hurdle hops', 'PLYOMETRIC', '["mini hurdles"]', 'Hop continuously over 4 to 6 low hurdles in rhythm. Quick rebound off ground with tall posture.', 'Keep torso quiet and eyes forward throughout.', false),
('lane-agility-drill', 'Lane agility drill', 'SPEED_AGILITY', '["basketball key","4 cones"]', 'Sprint up lane line, defensive slide across foul line, backpedal down lane line, slide across baseline.', 'Standard basketball agility test. Stay low on defensive slides without clicking heels.', false),
('pro-agility-5-10-5', 'Pro agility (5-10-5 shuttle)', 'SPEED_AGILITY', '["3 cones"]', 'Sprint 5m right, touch line with hand, sprint 10m left, touch line, sprint 5m through middle.', 'Drop hips low on turns and push forcefully off outside edge of foot.', false),
('reactive-cod', 'Reactive change of direction', 'SPEED_AGILITY', '["partner or visual cue"]', 'Sprint forward at 75% speed. React to coach/partner signal, plant outside foot, and cut 45 degrees.', 'Keep center of gravity low when planting.', false),
('defensive-closeout', 'Defensive closeout drill', 'SPEED_AGILITY', '["open space or court"]', 'Sprint toward perimeter shooter, chop feet to brake speed, contest high with lead hand, slide back.', 'Do not leave feet on shot fake; maintain balance and discipline.', false),
('pallof-press', 'Pallof press', 'CORE', '["resistance band or cable"]', 'Stand perpendicular to anchor. Hold handle at sternum, press straight out, resist rotation for 2 seconds.', 'Prevents rotational collapse during physical drives to the basket.', false),
('hanging-leg-raise', 'Hanging leg raise', 'CORE', '["pull-up bar"]', 'Hang from bar with active shoulders. Raise legs straight or bent past 90 degrees without swinging.', 'Control the lowering phase to work the abdominal wall eccentrically.', false),
('side-plank-abduction', 'Side plank with abduction', 'CORE', '["mat"]', 'Set up in side plank on elbow. Raise top leg 6 to 8 inches, hold body in straight rigid line.', 'Strengthens gluteus medius to stabilize knees during single-leg jump landings.', false),
('ankle-dorsiflexion-mob', 'Ankle dorsiflexion mobilization', 'MOBILITY', '["wall"]', 'Toes 3 to 4 inches from wall. Drive knee over second toe toward wall while keeping heel glued to floor.', 'Essential for deep landing mechanics, ankle mobility, and jumper knee prehab.', false),
('worlds-greatest-stretch', 'World greatest stretch', 'MOBILITY', '["none"]', 'Deep lunge with hands inside front foot. Rotate chest toward ceiling, rock back into hamstring stretch.', 'Comprehensive pre-workout hip, hamstring, and thoracic mobility opener.', false),
('tibialis-raise', 'Tibialis anterior raise', 'MOBILITY', '["wall or flat ground"]', 'Lean back against wall with heels 12 inches out. Flex toes up toward shins as high as possible, hold, lower.', 'Vital lower leg prehab for basketball players to prevent shin splints and absorb jumping force.', false)
